{
  "cards": [
    {
      "front": "What is the acceleration of an object at the highest point of its free-fall motion?",
      "back": "The acceleration remains non-zero because the gravitational force continues to act on the object. According to Newton's second law, $\\vec{F}_{grav} = m\\vec{a}$.",
      "source": "S4"
    },
    {
      "front": "How do a hammer and a feather fall when air resistance is negligible?",
      "back": "They fall with the same constant acceleration due to gravity. This characteristic applies wherever gravity acts without an atmosphere, such as on the Moon where $g = 1.67 \\text{ m/s}^2$.",
      "source": "S3"
    },
    {
      "front": "How do you decide on the sign of the acceleration of gravity in vertical motion problems?",
      "back": "Acceleration $g$ is negative if the positive direction is upward and the negative direction is downward. Alternatively, $g$ can be positive if you define the downward direction as positive.",
      "source": "S1"
    }
  ]
}
